(7091104, 1080215, 96751, '<td valign="top">There is a harshness to the editing which I don''t see in her work. But a sweet little guy, nevertheless.</td>', 'There is a harshness to the editing which I don''t see in her work. But a sweet little guy, nevertheless.', '2013-08-21 18:44:46.000000', NULL, 1),
(7091105, 1080180, 96751, '<td valign="top">Valiant try. But for me, this doesn''t really evoke John''s work. In addition to the use of color (which he uses, but rarely), there isn''t a story, and there is a lack of grain which is almost always present in his creations.</td>', 'Valiant try. But for me, this doesn''t really evoke John''s work. In addition to the use of color (which he uses, but rarely), there isn''t a story, and there is a lack of grain which is almost always present in his creations.', '2013-08-21 18:44:55.000000', NULL, 1),
(7091106, 1080162, 96751, '<td valign="top">I feel that this is much closer to Nick''s work than other attempts in the challenge. Nice use of contrast</td>', 'I feel that this is much closer to Nick''s work than other attempts in the challenge. Nice use of contrast', '2013-08-21 18:44:59.000000', NULL, 1),
(7091107, 1080211, 96751, '<td valign="top">Except for the fact that it''s a landscape, this fails to capture the light whcih Margaret has worked so hard to achieve</td>', 'Except for the fact that it''s a landscape, this fails to capture the light whcih Margaret has worked so hard to achieve', '2013-08-21 18:45:23.000000', NULL, 1),
(7091109, 1080203, 96751, '<td valign="top">It''s tougher than it looks, isn''t it.</td>', 'It''s tougher than it looks, isn''t it.', '2013-08-21 18:45:36.000000', NULL, 1),
